-- 0019 part 3 of 4: Vegetarian nutrition plans. Run the parts in order (part 1 adds the new foods).

-- Vegetarian: 14 plans, 1,400 to 4,000 kcal.
delete from public.templates where kind = 'nutrition' and name like 'Vegetarian, %kcal';
insert into public.templates (kind, name, summary, goal, level, audience, competitor, tags, body)
select 'nutrition', v.name, v.summary, v.goal, 'Beginner', 'any', 'any', v.tags::text[], v.body
from (values
('Vegetarian, 1,400 kcal', '1,400 kcal (5,858 kJ). Eggs, dairy, tofu, beans and lentils, with whey for an easy protein boost. Training and rest days, 3 meals and a snack.', 'General health', '{"vegetarian","trial","1400 kcal"}', $${"style":"plan","notes":"Eat roughly the same each day and don't stress about being exact. Hit your protein first. Training days swap the afternoon snack for a post-workout meal with more carbs. Weigh your food for the first week or two if you can, then hand portions are fine. Fill up on veg as much as you like.","day_types":[{"name":"Training day","weekdays":[1,2,4,5],"kcal":1400,"protein_g":96,"carbs_g":159,"fat_g":41,"fibre_g":25,"sodium_mg":null,"water_ml":null,"palms":4,"fists":4,"cupped":5,"thumbs":4,"notes":"Post-workout meal within an hour or so of training.","meals":[{"name":"Breakfast","notes":"Swap: 2 eggs on 2 slices of wholemeal toast instead of the oats and yoghurt, or skyr for the yoghurt.","items":[{"food":"Oats, rolled","grams":45},{"food":"Milk, semi-skimmed / light blue","grams":120},{"food":"Greek yoghurt, 0% fat","grams":130},{"food":"Frozen mixed berries","grams":60}]},{"name":"Lunch","notes":"Swap: 2 eggs or light mozzarella for the halloumi; lentils for the chickpeas; rice or couscous for the quinoa.","items":[{"food":"Chickpeas, tinned, drained","grams":70},{"food":"Quinoa, cooked","grams":90},{"food":"Halloumi","grams":50},{"food":"Spinach","grams":45},{"food":"Tomato","grams":70},{"food":"Olive oil","grams":5}]},{"name":"Post-workout","notes":"Within an hour or so of training. Swap: Per4m Isolate Zero or Strom NiHPRO for the whey; oats or rice cakes for the cream of rice.","items":[{"food":"Per4m Advanced Whey Protein","grams":25},{"food":"Strom Cream of Rice","grams":25},{"food":"Banana","grams":60}]},{"name":"Dinner","notes":"Swap: eggs, lentils or a veggie mince for the tofu; noodles or potatoes for the rice.","items":[{"food":"Tofu, firm","grams":170},{"food":"White rice, cooked","grams":120},{"food":"Frozen mixed veg","grams":130},{"food":"Soy sauce","grams":15}]}]},{"name":"Rest day","weekdays":[3,6,7],"kcal":1400,"protein_g":92,"carbs_g":146,"fat_g":46,"fibre_g":25,"sodium_mg":null,"water_ml":null,"palms":4,"fists":4,"cupped":5,"thumbs":5,"notes":null,"meals":[{"name":"Breakfast","notes":"Swap: 2 eggs on 2 slices of wholemeal toast instead of the oats and yoghurt, or skyr for the yoghurt.","items":[{"food":"Oats, rolled","grams":45},{"food":"Milk, semi-skimmed / light blue","grams":120},{"food":"Greek yoghurt, 0% fat","grams":130},{"food":"Frozen mixed berries","grams":60}]},{"name":"Lunch","notes":"Swap: 2 eggs or light mozzarella for the halloumi; lentils for the chickpeas; rice or couscous for the quinoa.","items":[{"food":"Chickpeas, tinned, drained","grams":70},{"food":"Quinoa, cooked","grams":90},{"food":"Halloumi","grams":50},{"food":"Spinach","grams":45},{"food":"Tomato","grams":70},{"food":"Olive oil","grams":5}]},{"name":"Snack","notes":"Swap: cottage cheese for the skyr, any fruit for the banana.","items":[{"food":"Skyr, plain","grams":130},{"food":"Banana","grams":70},{"food":"Almonds","grams":10}]},{"name":"Dinner","notes":"Swap: eggs, lentils or a veggie mince for the tofu; noodles or potatoes for the rice.","items":[{"food":"Tofu, firm","grams":170},{"food":"White rice, cooked","grams":120},{"food":"Frozen mixed veg","grams":130},{"food":"Soy sauce","grams":15}]}]}]}$$::jsonb),
